import jenkins.model.* import hudson.model.* import java.text.SimpleDateFormat import groovy.json.JsonOutput  def now = new Date() def sdf = new SimpleDateFormat("yyyy-MM-dd") def jobs = Jenkins.instance.getAllItems(Job.class) def builds = jobs.collectMany { it.builds }  // 🚀 Core Execution Metrics def totalJobsExecuted = builds.size()  def successCount = 0 def failureCount = 0 def durationSum = 0L def jobTriggerMap = [:] def jobDurationMap = [:] def jobTrendMap = [:]  builds.each { build ->     def result = build.result?.toString()     if (result == "SUCCESS") successCount++     else if (result == "FAILURE") failureCount++      def duration = build.duration ?: 0     durationSum += duration      def jobName = build.project.name     jobDurationMap[jobName] = jobDurationMap.get(jobName, []) + [duration]      def day = sdf.format(build.timestamp.time)     jobTrendMap[day] = jobTrendMap.get(day, 0) + 1      def cause = build.getCause(Cause.UserIdCause)     def trigger = cause?.userId ?: "SCM/Timer"     jobTriggerMap[trigger] = jobTriggerMap.get(trigger, 0) + 1 }  def avgDuration = durationSum / (totalJobsExecuted ?: 1) def longestJobs = jobDurationMap.collect { k, v -> [job: k, max: v.max()] }     .sort { -it.max }     .take(5)  def mostTriggeredJobs = jobTriggerMap.sort { -it.value }.take(5)  // 👤 User & Trigger Insights def executorSuccessMap = [:] def executorFailureMap = [:]  builds.each { build ->     def cause = build.getCause(Cause.UserIdCause)     def user = cause?.userId ?: "SCM/Timer"     def result = build.result?.toString()      if (result == "SUCCESS") {         executorSuccessMap[user] = executorSuccessMap.get(user, 0) + 1     } else if (result == "FAILURE") {         executorFailureMap[user] = executorFailureMap.get(user, 0) + 1     } }  // 📊 Output Summary [     "Total Jobs Executed": totalJobsExecuted,     "Success Count": successCount,     "Failure Count": failureCount,     "Average Duration (ms)": avgDuration,     "Longest Running Jobs": longestJobs,     "Most Frequent Triggers": mostTriggeredJobs,     "Execution Trend (by day)": jobTrendMap,     "Top Executors (Success)": executorSuccessMap.sort { -it.value }.take(5),     "Top Executors (Failure)": executorFailureMap.sort { -it.value }.take(5) ]   // Assuming 'metricsMap' holds your final output def metricsMap = [     "Total Jobs Executed": totalJobsExecuted,     "Success Count": successCount,     "Failure Count": failureCount,     "Average Duration (ms)": avgDuration,     "Longest Running Jobs": longestJobs,     "Most Frequent Triggers": mostTriggeredJobs,     "Execution Trend (by day)": jobTrendMap,     "Top Executors (Success)": executorSuccessMap.sort { -it.value }.take(5),     "Top Executors (Failure)": executorFailureMap.sort { -it.value }.take(5) ]  // Convert to pretty JSON def json = JsonOutput.prettyPrint(JsonOutput.toJson(metricsMap))  // Write to file (adjust path as needed) def file = new File("/tmp/metrics.json") file.write(json)  return "✅ Metrics written to metrics.json"
